// Writes go/internal/mcp/catalog_tools.go: every tool src/mcp.ts defines, in its order, with its group, its `when` and
// its {name, description, inputSchema} as JSON.stringify writes them, for Catalog (src/mcp.ts toolCatalog, S-3776).
// The Go MCP server serves only the tools it ports (tools.go); Settings › Tools and the inventory list them all.
// Run it when src/mcp.ts changes a tool; catalog_test.go compares Catalog with toolCatalog.
//
//   node go/internal/mcp/testdata/gencatalog.mjs > go/internal/mcp/catalog_tools.go && gofmt -w go/internal/mcp/catalog_tools.go
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const home = mkdtempSync(join(tmpdir(), 'stam-gencatalog-'));
// src/env.ts reads MOOTR_X before STAM_X, so the MOOTR_ twins go and the STAM_ names below are the ones read.
for (const k of Object.keys(process.env)) if (k.startsWith('MOOTR_')) delete process.env[k];
process.env.STAM_HOME = home;
process.env.STAM_MACHINE = 'test-machine';
process.env.STAM_EMBEDDER = 'stub';
for (const k of ['STAM_URL', 'STAM_TOKEN', 'STAM_AGENT_ID', 'STAM_PORT', 'STAM_RELEASE_ID']) delete process.env[k];
const { tools } = await import('../../../../src/mcp.ts');

let out = `// Code generated by testdata/gencatalog.mjs; DO NOT EDIT.\n\npackage mcp\n\n// catalogTools is every tool src/mcp.ts defines, in its order: its group, its \`when\` ("" for always) and its\n// {name, description, inputSchema} as JSON.stringify writes them (generated by testdata/gencatalog.mjs; catalog_test.go compares).\nvar catalogTools = []catalogTool{\n`;
for (const { name, description, inputSchema, group, when } of tools) {
  out += `\t{${JSON.stringify(group)}, ${JSON.stringify(when ?? '')}, ${JSON.stringify(JSON.stringify({ name, description, inputSchema }))}},\n`;
}
process.stdout.write(out + '}\n');
rmSync(home, { recursive: true, force: true });
process.exit(0);
